import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.UpdateAttributes{EntityRuntimeID: 300, Tick: 1000,
# Attributes: []protocol.Attribute{
# {AttributeValue: protocol.AttributeValue{Name: "minecraft:health", Min: 0, Max: 20, Value: 17},
# DefaultMin: 0, DefaultMax: 20, Default: 20,
# Modifiers: []protocol.AttributeModifier{{ID: "00000000-0000-0000-0000-000000000001",
# Name: "buff", Amount: 2.5, Operation: protocol.AttributeModifierOperationMultiplyBase,
# Operand: protocol.AttributeModifierOperandCurrent, Serializable: true}}},
# {AttributeValue: protocol.AttributeValue{Name: "minecraft:movement", Min: 0, Max: 1, Value: 0.25},
# DefaultMin: 0, DefaultMax: 1, Default: 0.5}}}
UPDATE_ATTRIBUTES = bytes.fromhex(
    "ac0202000000000000a04100008841000000000000a0410000a041106d696e6563726166743a6865616c7468"
    "012430303030303030302d303030302d303030302d303030302d303030303030303030303031046275666600"
    "002040010000000200000001000000000000803f0000803e000000000000803f0000003f126d696e65637261"
    "66743a6d6f76656d656e7400e807"
)

PACKET = v2225.UpdateAttributesPacket(
    runtime_id=300,
    attribute_data=[
        v2225.AttributeData(
            min_value=0.0,
            max_value=20.0,
            current_value=17.0,
            default_min_value=0.0,
            default_max_value=20.0,
            default_value=20.0,
            name="minecraft:health",
            modifiers=[
                v2225.AttributeModifier(
                    id="00000000-0000-0000-0000-000000000001",
                    name="buff",
                    amount=2.5,
                    operation=v2225.AttributeModifierOperation.OPERATION_MULTIPLY_BASE,
                    operand=v2225.AttributeOperands.OPERAND_CURRENT,
                    serialize=True,
                )
            ],
        ),
        v2225.AttributeData(
            min_value=0.0,
            max_value=1.0,
            current_value=0.25,
            default_min_value=0.0,
            default_max_value=1.0,
            default_value=0.5,
            name="minecraft:movement",
        ),
    ],
    tick=1000,
)


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_update_attributes_is_packet_29(version):
    assert version.PACKETS[29] is version.UpdateAttributesPacket


def test_update_attributes_encodes_to_its_golden():
    assert bytes(PACKET) == UPDATE_ATTRIBUTES


def test_update_attributes_decodes_from_its_golden():
    assert v2225.UpdateAttributesPacket.from_bytes(UPDATE_ATTRIBUTES) == PACKET


def test_an_empty_attribute_list_still_carries_its_count_byte_and_the_tick():
    packet = v2225.UpdateAttributesPacket(runtime_id=0, attribute_data=[], tick=300)
    assert len(bytes(packet)) == 4
    assert v2225.UpdateAttributesPacket.from_bytes(bytes(packet)) == packet


@pytest.fixture
def invalid_modifier_packet():
    return v2225.UpdateAttributesPacket(
        attribute_data=[
            v2225.AttributeData(
                modifiers=[
                    v2225.AttributeModifier(
                        operation=v2225.AttributeModifierOperation.OPERATION_INVALID,
                        operand=v2225.AttributeOperands.OPERAND_INVALID,
                        serialize=False,
                    )
                ]
            )
        ]
    )


def test_the_operation_and_operand_sentinels_round_trip(invalid_modifier_packet):
    assert v2225.UpdateAttributesPacket.from_bytes(bytes(invalid_modifier_packet)) == invalid_modifier_packet


def test_the_operation_sentinel_reads_back_as_its_duplicate_value(invalid_modifier_packet):
    back = v2225.UpdateAttributesPacket.from_bytes(bytes(invalid_modifier_packet))
    assert back.attribute_data[0].modifiers[0].operation == v2225.AttributeModifierOperation.TOTAL_OPERATIONS


def test_the_operand_sentinel_reads_back_as_its_duplicate_value(invalid_modifier_packet):
    back = v2225.UpdateAttributesPacket.from_bytes(bytes(invalid_modifier_packet))
    assert back.attribute_data[0].modifiers[0].operand == v2225.AttributeOperands.TOTAL_OPERANDS
